package history
import"testing"
func TestBuildVerifiesDigestAndPreservesMissingSignals(t *testing.T){c:=Content{Repository:"o/r",Revision:"a",CreatedAt:"2026",Signals:[]Signal{{Name:"coverage",Value:80,Scale:"percent",Provenance:"ci"}}};r:=Receipt{SchemaVersion:"1.0.0",Digest:Digest(c),Content:c};report,err:=Build([]Receipt{r});if err!=nil||len(report.Receipts[0].Content.Signals)!=1{t.Fatal(err)};r.Content.Revision="b";if _,err:=Build([]Receipt{r});err==nil{t.Fatal("expected tamper rejection")}}
func TestBuildEmitsSeparateTrendsAndAbsentStaysAbsent(t *testing.T){a:=Content{Repository:"o/r",Revision:"a",CreatedAt:"1",Signals:[]Signal{{Name:"coverage",Value:80,Scale:"percent",Provenance:"ci"}}};b:=Content{Repository:"o/r",Revision:"b",CreatedAt:"2",Signals:nil};report,err:=Build([]Receipt{{SchemaVersion:"1.0.0",Digest:Digest(a),Content:a},{SchemaVersion:"1.0.0",Digest:Digest(b),Content:b}});if err!=nil||len(report.Trends)!=1||len(report.Trends[0].Points)!=1{t.Fatalf("%+v %v",report,err)}}

func TestTrendOrderingIncludesScale(t *testing.T){c:=Content{Repository:"o/r",Revision:"a",CreatedAt:"1",Signals:[]Signal{{Name:"x",Scale:"z",Provenance:"a"},{Name:"x",Scale:"a",Provenance:"z"}}};report,err:=Build([]Receipt{{SchemaVersion:"1.0.0",Digest:Digest(c),Content:c}});if err!=nil||report.Trends[0].Scale!="a"{t.Fatalf("%+v %v",report,err)}}
func TestStrictHistoryEOF(t *testing.T){if _,err:=ParseReceipt([]byte(`{"schema_version":"1.0.0","digest":"x","content":{}} {}`));err==nil{t.Fatal("expected trailing rejection")};if _,err:=ParseApproval([]byte(`{"schema_version":"1.0.0","repository":"o/r","receipt_digests":["x"]} {}`));err==nil{t.Fatal("expected trailing rejection")}}
